// Decorative connections follow the tablet within the cropped photograph.
function layoutTabletConnections(){
 const photo=document.querySelector('.person-photo'),svg=document.querySelector('.tablet-connections');
 if(!photo||!svg||!photo.naturalWidth)return;
 const r=photo.getBoundingClientRect(),host=svg.getBoundingClientRect();if(!r.width||!host.width)return;
 const scale=Math.max(r.width/photo.naturalWidth,r.height/photo.naturalHeight);
 const ox=r.left-host.left+(r.width-photo.naturalWidth*scale)/2,oy=r.top-host.top+(r.height-photo.naturalHeight*scale)/2;
 const y=oy+photo.naturalHeight*.415*scale;
 document.querySelectorAll('.hero-parts .part-card').forEach((card,i)=>{
  const q=card.getBoundingClientRect(),left=i%2===0;
  const x=ox+photo.naturalWidth*(left?.437:.501)*scale;
  const ex=(left?q.right:q.left)-host.left,ey=q.top-host.top+q.height*.55;
  const cx=x+(left?-42:42);
  svg.children[i].setAttribute('d',`M ${x} ${y} C ${cx} ${y}, ${ex} ${y}, ${ex} ${ey}`);
 });
}
const tabletPhoto=document.querySelector('.person-photo');tabletPhoto.addEventListener('load',layoutTabletConnections);
window.addEventListener('resize',layoutTabletConnections);layoutTabletConnections();
if(typeof ResizeObserver!=='undefined')new ResizeObserver(layoutTabletConnections).observe(document.querySelector('.hero-person'));

