function quickHtml50(){const r=quickCalc50();return `<section class="quick50"><div><div class="eyebrow">Ориентир для вашей квартиры</div><h2>Какой бюджет планировать?</h2><p>Укажите площадь и количество комнат. Получите предварительный ориентир для типовой планировки.</p><p class="scope">Демонстрационные ставки. Точный состав зависит от планировки, выбранных товаров и технологий ремонта.</p></div><div><form id="quick-form50"><div class="quick-fields50"><label>Площадь, м²<input type="number" name="area" min="20" max="200" step="0.1" required value="${quick50.area}"></label><label>Количество комнат<select name="rooms">${[1,2,3,4,5].map(n=>`<option value="${n}" ${+quick50.rooms===n?'selected':''}>${n===1?'Студия / 1 комната':n+' комнаты'}</option>`).join('')}</select></label><label>Вариант<select name="level">${['Базовый','Оптимальный','Комфортный'].map((n,i)=>`<option value="${i}" ${+quick50.level===i?'selected':''}>${n}</option>`).join('')}</select></label></div><button class="btn" type="submit">Рассчитать ориентир</button></form><div class="quick-result50" aria-live="polite"><small>${quick50.area} м² · ${quick50.rooms} комн. · ${['Базовый','Оптимальный','Комфортный'][quick50.level]}</small><div class="adapt-total">${money(r.furniture+r.materials+r.works)}</div><div class="adapt-breakdown"><div><span>Мебель и оснащение</span><b>${money(r.furniture)}</b></div><div><span>Материалы</span><b>${money(r.materials)}</b></div><div><span>Работы</span><b>${money(r.works)}</b></div></div><p class="scope">Общий ориентир не изменяет сметы квартир в каталоге. Для подробного расчёта откройте квартиру и настройте её комнаты.</p></div></div></section>`}
