function groupName51(n){n=n.toLowerCase();return /диван/.test(n)?'sofas':/кровать|матрас/.test(n)?'beds':/наполь/.test(n)?'floors':/керамогранит/.test(n)?'tiles':/смеситель|душ|ванна|унитаз|раковин/.test(n)?'bath':/розет|выключ|рамка|полотенц/.test(n)?'electrics':/свет|бра/.test(n)?'lighting':/краска|стен|плинтус|двер|потол|молдинг|карниз/.test(n)?'walls':/штор|ковер|картин|зеркал/.test(n)?'decor':'storage'}
