function initRoom51(x){const base=sourceArea51(x);return {area:base,height:2.7,level:0,edited:false,variants:[0,1,2].map(t=>{let rows;if(x.lines){rows=x.lines.map((l,j)=>{const p=f51(l.catalogId),m=l.qty.match(/^\s*([\d.,]+)\s*(шт|м2|м²)/i),count=m?parseFloat(m[1].replace(',','.')):1,unit=m&&/м/.test(m[2])?'м²':m?'шт.':'компл.';const totals=l.values.length>1?[l.values[0],(l.values[0]+l.values[1])/2,l.values[1]]:[l.values[0],l.values[0],l.values[0]];return {id:j,pid:l.catalogId||'',name:l.description||l.name,short:l.name,image:l.image||'',group:p?.group||groupName51(l.name),count,basecount:count,unit,rate:totals[t]/count,areaBased:unit==='м²',custom:!m,source:true}})}else{const d=newDraft(x);d.level=t;rows=estimate49(x,d).rows.map((p,j)=>({id:j,pid:p.id,name:p.name,short:p.name,image:p.image,group:p.group==='sofa'?'sofas':p.group==='bed'?'beds':p.group==='floor'?'floors':p.group==='tile'?'tiles':p.group==='bath'?'bath':p.group==='light'?'lighting':p.group==='table'?'tables':'storage',count:p.count,basecount:p.count,unit:p.unit,rate:p.price,pack:p.pack,areaBased:!!p.pack,source:false}));}return {rows}})}}
