function apTotal51(x){const ids=apRooms51(x),rows=ids.map(id=>({x:item(id),r:estimate51(item(id)),s:rd51(item(id))}));return {rows,total:rows.reduce((n,p)=>n+p.r.total,0),g:rows.reduce((n,p)=>n+p.r.g,0),mat:rows.reduce((n,p)=>n+p.r.mat,0),rough:rows.reduce((n,p)=>n+p.r.rough,0),w:rows.reduce((n,p)=>n+p.r.w,0),area:rows.reduce((n,p)=>n+p.s.area,0)}}
