function apGlobal51(x){const state=A51[x.id]||{},level=state.level||0;return `<details class="apt-global51" ${state.quick?'open':''}><summary>Рассчитать для моей квартиры <span>+</span></summary><form id="apt-form51" data-id="${x.id}"><div class="adapt-fields"><label>Площадь квартиры, м²<input name="area" required type="number" min="20" max="200" step="0.1" value="${state.area||x.area}"></label><label>Количество комнат<select name="rooms">${[1,2,3,4,5].map(n=>`<option value="${n}" ${(state.rooms||parseInt(x.room)||2)===n?'selected':''}>${n===1?'Студия / 1 комната':n+' комнаты'}</option>`).join('')}</select></label></div><button class="btn" type="submit">Получить ориентир</button></form>${state.quick?`<div class="quick-result51"><small>${state.area} м² · ${state.rooms} комн. · ${['Базовый','Оптимальный','Комфортный'][level]}</small><div class="adapt-total">${money(quickBudget51(state.area,state.rooms,level))}</div><p class="scope">Ориентир для типовой квартиры. Уточните состав и площади помещений для подробного расчёта.</p><button class="btn secondary" data-ap51="setup" data-id="${x.id}">Уточнить расчёт по комнатам →</button></div>`:''}</details>`}
function quickBudget51(area,n,t){return n*[160000,240000,360000][t]+[160000,240000,350000][t]+area*([7500,11000,16000][t]+[13000,16000,20000][t])}
apartment=function(x){baseApartment51(x);const state=A51[x.id]||(A51[x.id]={level:0}),r=apTotal51(x);document.querySelectorAll('.workspending').forEach(n=>n.remove());const budget=$('.apartmentbudget');budget.innerHTML=`<div><div class="eyebrow">Общий бюджет</div><h2>Стоимость всей квартиры</h2><p>Мебель, отделочные и черновые материалы, ремонтные работы — в одном расчёте.</p>${apGlobal51(x)}<p class="scope">Площадь помещений в текущем расчёте: ${r.area.toFixed(2)} м². Площадь исходного проекта: ${x.area} м². Площади уточняются по планировке.</p></div><div><div class="adapt-levels">${['Базовый','Оптимальный','Комфортный'].map((n,i)=>`<button data-ap51="level" data-id="${x.id}" data-n="${i}" aria-pressed="${state.level===i}">${n}</button>`).join('')}</div><div class="adapt-total" id="ap-total51">${money(r.total)}</div><div class="adapt-breakdown">${[['Мебель и оснащение',r.g],['Отделочные материалы',r.mat],['Черновые материалы',r.rough],['Ремонтные работы',r.w]].map(([n,v])=>`<div><span>${n}</span><b>${money(v)}</b></div>`).join('')}</div><p class="scope">Сумма текущих расчётов всех помещений. Изменение комнаты автоматически обновляет этот итог.</p><button class="btn" data-ap51="save" data-id="${x.id}">Сохранить мой вариант квартиры</button><p class="scope" id="apt-save51">Ваш вариант сохраняется на этом устройстве.</p><p class="scope">Доставка, сборка и проектные услуги уточняются отдельно.</p></div>`;$('.apthero').after(budget);const rooms=budget.nextElementSibling;if(rooms?.querySelector('.grid')){rooms.innerHTML=`<div class="row"><div><h2>Посмотрите каждое помещение</h2><p class="muted">Уточняйте площади и заменяйте товары — общий бюджет обновится.</p></div></div>${apNav51(x,'')}<div class="grid">${apRooms51(x).map(id=>card(item(id))).join('')}</div>`}store51()};
listing=function(kind){baseListing51(kind)};
render=function(){baseRender49();document.title=($('#app h1')?.textContent||'Интерьеры')+' · ZETTA HOME · V51';};
// Catalog alternatives are scoped to the replaced item category.
function candidates51(row){let g=row.group;let ps=P51.filter(p=>p.group===g);if(g==='sofas')ps=[...AD.products.map(p=>({...p,group:g,unit:'шт.'})),...ps];if(ps.length<2){const legacy=Object.entries(demoGoods).flatMap(([k,p])=>p).filter(p=>p.unit===row.unit&&p.id!==row.pid&&((g==='floors'&&p.id.startsWith('floor'))||(g==='tiles'&&p.id.startsWith('tile'))||(g==='beds'&&p.id.startsWith('bed'))||(g==='storage'&&p.id.startsWith('store'))||(g==='lighting'&&p.id.startsWith('light'))||(g==='tables'&&p.id.startsWith('table'))||(g==='bath'&&p.id.startsWith('bath'))));ps.push(...legacy)}return ps.filter((p,i,a)=>a.findIndex(q=>q.id===p.id)===i)}
function openReplace51(id){const x=item(room51),s=rd51(x),row=s.variants[s.level].rows.find(r=>r.id===id);replacement51=id;pending51=null;let d=$('#replace51');if(!d){d=document.createElement('dialog');d.id='replace51';d.className='replacement-dialog';document.body.append(d)}d.innerHTML=`<button class="close" data-r51="close" aria-label="Закрыть">×</button><div class="eyebrow">Замена товара</div><h2>${esc(row.short)}</h2><p class="scope">Выберите товар того же назначения. Размеры и совместимость уточняются по вашей планировке.</p><input id="replace-search51" placeholder="Поиск в категории" class="replace-search51"><div class="replacement-grid" id="replace-grid51"></div><div class="replacement-preview" id="replace-preview51"><p>Выберите товар, чтобы увидеть изменение бюджета.</p></div>`;drawReplace51();d.showModal()}
function drawReplace51(){const row=rd51(item(room51)).variants[rd51(item(room51)).level].rows.find(r=>r.id===replacement51),q=$('#replace-search51').value.toLowerCase();$('#replace-grid51').innerHTML=candidates51(row).filter(p=>p.name.toLowerCase().includes(q)).map(p=>`<button class="replacement-card" data-r51="candidate" data-pid="${p.id}" aria-pressed="${pending51===p.id}"><img src="${p.image}" alt="${esc(p.name)}"><h3>${esc(p.name)}</h3><strong>${money(p.price)} / ${p.unit||'шт.'}</strong></button>`).join('');if(pending51){const p=f51(pending51)||AD.products.find(p=>p.id===pending51),x=item(room51),r=estimate51(x),old=r.rows.find(r=>r.id===replacement51),delta=Math.round(old.count*p.price-old.sum);$('#replace-preview51').innerHTML=`<p><b>${esc(p.name)}</b></p><p>Бюджет комнаты: ${money(r.total)} → <b>${money(r.total+delta)}</b></p><p>${delta>=0?'+':'−'}${money(Math.abs(delta))}</p><button class="btn" data-r51="apply">Заменить в смете</button>`}}
function showSetup51(x){const st=A51[x.id],ids=[...x.children],living=ids.filter(id=>!/коридор|прихож|ванн|сануз/i.test(item(id).room));let selected=[...ids];while(living.length<st.rooms){const source=ITEMS.find(y=>y.type==='room'&&/спальн/i.test(y.room))||item(living[0]);const id=x.id+'extra'+living.length;let y=item(id);if(!y){y={...source,id,parent:x.id,title:'Спальня '+living.length,room:'Спальня',image:source.image,lines:undefined,area:12,plan:undefined};ITEMS.push(y)}living.push(id);selected.push(id)}while(living.length>st.rooms){let id=living.pop();selected=selected.filter(n=>n!==id)}let totalarea=selected.reduce((n,id)=>n+sourceArea51(item(id)),0);let d=$('#setup51');if(!d){d=document.createElement('dialog');d.id='setup51';d.className='replacement-dialog';document.body.append(d)}d.innerHTML=`<button class="close" data-setupclose51>×</button><h2>Площади помещений</h2><p>Предварительно распределили ${st.area} м². Уточните площади по вашей планировке. Исходный план квартиры остаётся образцом.</p><form id="setup-form51" data-id="${x.id}">${selected.map(id=>`<label class="setup-row51">${esc(item(id).room)}<input name="${id}" type="number" min="2" max="100" step="0.01" required value="${(st.area*sourceArea51(item(id))/totalarea).toFixed(2)}"> м²</label>`).join('')}<p id="setup-error51" class="adapt-error"></p><button class="btn">Применить площади и открыть расчёт</button></form>`;d.showModal()}
document.addEventListener('click',e=>{let b=e.target.closest('[data-r51]');if(b){const x=item(room51),s=rd51(x),a=b.dataset.r51;if(a==='level'){s.level=+b.dataset.n;if(x.parent){A51[x.parent]??={};A51[x.parent].level=s.level;apRooms51(item(x.parent)).forEach(id=>rd51(item(id)).level=s.level)}detail(x)}if(a==='replace')openReplace51(+b.dataset.row);if(a==='close')$('#replace51').close();if(a==='candidate'){pending51=b.dataset.pid;drawReplace51()}if(a==='apply'){const p=f51(pending51)||AD.products.find(p=>p.id===pending51),row=s.variants[s.level].rows.find(r=>r.id===replacement51);Object.assign(row,{pid:p.id,name:p.name,short:p.short||p.name,image:p.image,rate:p.price,replaced:true});s.edited=true;$('#replace51').close();detail(x);$('#goods51').scrollIntoView({block:'start'});toast('Товар заменён. Бюджет обновлён.')}if(a==='save'){store51();$('#save51').textContent=x.parent?'Сохранён весь вариант квартиры: помещения, товары и расчёт.':'Расчёт сохранён на этом устройстве.'}if(a==='plan'){const plan=x.plan||item(x.parent)?.plan;$('#lightbox').innerHTML=`<div class="dialoghead"><h3>Планировка</h3><button data-action="closelight" class="close">×</button></div><img src="${plan}" style="width:100%" alt="Планировка">`;$('#lightbox').showModal()}}b=e.target.closest('[data-ap51]');if(b){const x=item(b.dataset.id),a=b.dataset.ap51;A51[x.id]??={level:0};if(a==='level'){A51[x.id].level=+b.dataset.n;apRooms51(x).forEach(id=>rd51(item(id)).level=+b.dataset.n);apartment(x)}if(a==='setup')showSetup51(x);if(a==='save'){store51();$('#apt-save51').textContent='Вариант квартиры сохранён: все помещения, площади и выбранные товары.'}}if(e.target.closest('[data-setupclose51]'))$('#setup51').close();store51()});
document.addEventListener('input',e=>{if(e.target.id==='replace-search51')drawReplace51()});
document.addEventListener('change',e=>{if(e.target.dataset.qty51!==undefined){const n=+e.target.value;if(!Number.isInteger(n)||n<0||n>100)return;const x=item(room51),s=rd51(x);s.variants[s.level].rows.find(r=>r.id===+e.target.dataset.qty51).count=n;s.edited=true;let y=scrollY;detail(x);scrollTo(0,y);store51()}});
document.addEventListener('submit',e=>{const f=e.target;if(f.id==='room-form51'){e.preventDefault();if(!f.checkValidity())return;const x=item(room51),s=rd51(x);s.area=+f.elements.area.value;s.height=+f.elements.height.value;s.edited=true;detail(x);toast('Площадь учтена в расчёте');store51()}if(f.id==='apt-form51'){e.preventDefault();if(!f.checkValidity())return;const x=item(f.dataset.id),st=A51[x.id];Object.assign(st,{area:+f.elements.area.value,rooms:+f.elements.rooms.value,quick:true});apartment(x);store51()}if(f.id==='setup-form51'){e.preventDefault();if(!f.checkValidity())return;const x=item(f.dataset.id),st=A51[x.id],fields=[...f.querySelectorAll('input')],sum=fields.reduce((n,i)=>n+(+i.value),0);if(Math.abs(sum-st.area)>.25){$('#setup-error51').textContent='Сумма площадей '+sum.toFixed(2)+' м². Укажите площади общей суммой '+st.area+' м².';return}st.ids=fields.map(f=>f.name);for(const i of fields){const s=rd51(item(i.name));s.area=+i.value;s.level=st.level;s.edited=true}$('#setup51').close();apartment(x);store51()}});

